package org.apache.ibatis.reflection;

/**
 * Simple driver to demonstrate the getSetterType bug.
 * This test demonstrates that getSetterType throws NPE instead of ReflectionException
 * when called with a property that has no setter.
 * 
 * Run with: mvn test -Dtest=ReflectorBugDriverTest
 */
public class ReflectorBugDriverTest {

    public static void main(String[] args) {
        ReflectorFactory reflectorFactory = new DefaultReflectorFactory();
        Reflector reflector = reflectorFactory.findForClass(SimpleBean.class);

        // Compare getter vs setter behavior
        System.out.println("=== Testing getGetterType with nonexistent property ===");
        try {
            Class<?> type = reflector.getGetterType("nonexistent");
            System.out.println("getGetterType: No exception thrown. Got type: " + type);
        } catch (ReflectionException e) {
            System.out.println("getGetterType: CORRECT - ReflectionException: " + e.getMessage());
        } catch (NullPointerException e) {
            System.out.println("getGetterType: BUG - NullPointerException: " + e.getMessage());
        }

        System.out.println("\n=== Testing getSetterType with nonexistent property ===");
        // This should throw ReflectionException, but actually throws NullPointerException
        try {
            Class<?> type = reflector.getSetterType("nonexistent");
            System.out.println("BUG: Expected exception was NOT thrown. Got type: " + type);
            System.exit(1);
        } catch (ReflectionException e) {
            System.out.println("CORRECT: ReflectionException was thrown: " + e.getMessage());
            System.exit(0);
        } catch (NullPointerException e) {
            System.out.println("BUG: NullPointerException was thrown instead of ReflectionException: " + e.getMessage());
            System.exit(1);
        } catch (Exception e) {
            System.out.println("BUG: Unexpected exception type: " + e.getClass().getName() + ": " + e.getMessage());
            System.exit(1);
        }
    }

    static class SimpleBean {
        private String name;
        public String getName() { return name; }
        public void setName(String name) { this.name = name; }
    }
}

