package org.apache.ibatis.cache.decorators;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;

import org.apache.ibatis.cache.Cache;
import org.junit.jupiter.api.Test;

/**
 * Regression test for lock leak in BlockingCache when delegate.getObject returns null.
 * In the buggy code, releaseLock is only called when value != null, so when the delegate
 * returns null, the lock is never released and subsequent threads block indefinitely.
 */
class BlockingCacheNullLockLeakTest {

  @Test
  void ensureLockReleasedWhenDelegateReturnsNull() throws Exception {
    // Create a delegate cache that always returns null from getObject
    final BlockingCache blockingCache = new BlockingCache(new Cache() {
      @Override
      public String getId() {
        return "test-cache";
      }

      @Override
      public int getSize() {
        return 0;
      }

      @Override
      public Object getObject(Object key) {
        // Simulate cache miss - returns null
        return null;
      }

      @Override
      public void putObject(Object key, Object value) {
        // no-op
      }

      @Override
      public Object removeObject(Object key) {
        return null;
      }

      @Override
      public void clear() {
        // no-op
      }
    });
    blockingCache.setTimeout(500);

    final Object lockKey = "key";

    // Thread 1: call getObject which acquires lock, gets null, and (in buggy code) leaks lock
    Thread thread1 = new Thread(() -> {
      try {
        blockingCache.getObject(lockKey);
      } catch (Exception e) {
        // ignore timeout exceptions
      }
    });
    thread1.start();

    // Give thread 1 time to acquire the lock
    Thread.sleep(300);

    // Main thread: call getObject on same key - should complete if lock was released
    // On buggy code: this will timeout (lock leaked), throwing CacheException
    // On fixed code: lock was released, so this completes normally
    assertDoesNotThrow(() -> {
      blockingCache.getObject(lockKey);
    }, "Lock was not released when delegate returned null - lock leaked. "
        + "Expected the lock to be released even when delegate.getObject returns null.");

    thread1.join(2000);
    if (thread1.isAlive()) {
      thread1.interrupt();
    }
  }
}

