package org.apache.ibatis.reflection.property;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * @author <a href="1181963012mw@gmail.com">mawen12</a>
 *
 * @see PropertyTokenizer
 */
class PropertyTokenizerTest {

  @Test
  void shouldParsePropertySuccessfully() {
    String fullname = "id";
    PropertyTokenizer tokenizer = new PropertyTokenizer(fullname);

    assertEquals("id", tokenizer.getIndexedName());
    assertEquals("id", tokenizer.getName());

    assertNull(tokenizer.getChildren());
    assertNull(tokenizer.getIndex());
    assertFalse(tokenizer.hasNext());
    assertNull(tokenizer.getIndex());

    assertThrows(UnsupportedOperationException.class, tokenizer::remove);
  }

  @Test
  void shouldParsePropertyWhichContainsDelimSuccessfully() {
    String fullname = "person.id";
    PropertyTokenizer tokenizer = new PropertyTokenizer(fullname);

    assertEquals("person", tokenizer.getIndexedName());
    assertEquals("person", tokenizer.getName());
    assertTrue(tokenizer.hasNext());
    assertEquals("id", tokenizer.getChildren());

    assertNull(tokenizer.getIndex());

    assertThrows(UnsupportedOperationException.class, tokenizer::remove);
  }

  @Test
  void shouldParsePropertyWhichContainsIndexSuccessfully() {
    String fullname = "array[0]";
    PropertyTokenizer tokenizer = new PropertyTokenizer(fullname);

    assertEquals("array[0]", tokenizer.getIndexedName());
    assertEquals("array", tokenizer.getName());
    assertEquals("0", tokenizer.getIndex());

    assertFalse(tokenizer.hasNext());
    assertNull(tokenizer.getChildren());

    assertThrows(UnsupportedOperationException.class, tokenizer::remove);
  }

  @Test
  void shouldThrowExceptionForUnclosedBracket() {
    String fullname = "foo[bar";
    assertThrows(IllegalArgumentException.class, () -> new PropertyTokenizer(fullname));
  }

  public static void main(String[] args) {
    boolean passed = true;
    String failMsg = "";

    // Test 1: Normal property - should parse fine
    try {
      PropertyTokenizer t1 = new PropertyTokenizer("id");
      if (!"id".equals(t1.getName()) || !"id".equals(t1.getIndexedName())) {
        passed = false;
        failMsg = "Test 1 failed: normal property parse";
      }
    } catch (Exception e) {
      passed = false;
      failMsg = "Test 1 failed: " + e;
    }

    // Test 2: Property with index - should parse fine
    try {
      PropertyTokenizer t2 = new PropertyTokenizer("array[0]");
      if (!"array".equals(t2.getName()) || !"0".equals(t2.getIndex())) {
        passed = false;
        failMsg = "Test 2 failed: indexed property parse";
      }
    } catch (Exception e) {
      passed = false;
      failMsg = "Test 2 failed: " + e;
    }

    // Test 3: Unclosed bracket - SHOULD throw IllegalArgumentException
    try {
      PropertyTokenizer t3 = new PropertyTokenizer("foo[bar");
      // If we get here, the bug exists - no exception was thrown
      String name = t3.getName();
      String index = t3.getIndex();
      // Check what values we got - demonstrates the truncation bug
      if (!"foo".equals(name) || !"ba".equals(index)) {
        System.out.println("BUG DETECTED: unclosed bracket did NOT throw exception");
        System.out.println("  name = '" + name + "' (expected 'foo')");
        System.out.println("  index = '" + index + "' (expected 'bar' or exception)");
        System.out.println("  The last char 'r' was silently truncated!");
        passed = false;
        failMsg = "should have thrown IllegalArgumentException";
      } else {
        System.out.println("BUG DETECTED: unclosed bracket did NOT throw exception");
        System.out.println("  name = '" + name + "'");
        System.out.println("  index = '" + index + "' (last char silently truncated)");
        passed = false;
        failMsg = "should have thrown IllegalArgumentException";
      }
    } catch (IllegalArgumentException e) {
      // This is the correct behavior - exception was thrown
      System.out.println("CORRECT: IllegalArgumentException thrown for unclosed bracket");
    } catch (Exception e) {
      passed = false;
      failMsg = "Wrong exception type: " + e.getClass() + " - " + e.getMessage();
    }

    if (passed) {
      System.out.println("ALL TESTS PASSED");
      System.exit(0);
    } else {
      System.out.println("TEST FAILED: " + failMsg);
      System.exit(1);
    }
  }
}

package org.apache.ibatis.type;

/**
 * Standalone test to verify JdbcType.forCode() behavior for unknown type codes.
 * Run with: java -ea -cp classes:target/test-classes org.apache.ibatis.type.JdbcTypeForCodeNullTest
 */
public class JdbcTypeForCodeNullTest {

  public static void main(String[] args) {
    boolean allPassed = true;

    // Test 1: JdbcType.forCode(-101) should not return null
    JdbcType jdbcType = JdbcType.forCode(-101);
    if (jdbcType == null) {
      System.out.println("FAIL: JdbcType.forCode(-101) returned null - this causes NPE in ResultSetWrapper/Jdbc3KeyGenerator");
      allPassed = false;
    } else {
      System.out.println("PASS: JdbcType.forCode(-101) returned " + jdbcType);
    }

    // Test 2: Another vendor-specific type code
    JdbcType jdbcType2 = JdbcType.forCode(-200);
    if (jdbcType2 == null) {
      System.out.println("FAIL: JdbcType.forCode(-200) returned null");
      allPassed = false;
    } else {
      System.out.println("PASS: JdbcType.forCode(-200) returned " + jdbcType2);
    }

    // Test 3: Known type codes should still work
    JdbcType varchar = JdbcType.forCode(java.sql.Types.VARCHAR);
    if (varchar != JdbcType.VARCHAR) {
      System.out.println("FAIL: JdbcType.forCode(VARCHAR) returned " + varchar + " instead of VARCHAR");
      allPassed = false;
    } else {
      System.out.println("PASS: JdbcType.forCode(VARCHAR) returned VARCHAR");
    }

    if (!allPassed) {
      System.out.println("\nTESTS FAILED");
      System.exit(1);
    } else {
      System.out.println("\nALL TESTS PASSED");
      System.exit(0);
    }
  }
}

